// Babylon Lite — Public API
// Tree-shakable: import only what you use.

// ─── Core ────────────────────────────────────────────────────────────
export {
    createEngine,
    startEngine,
    stopEngine,
    renderFrame,
    resizeEngine,
    setEngineSize,
    disposeEngine,
    setGpuTimingEnabled,
    isGpuTimingSupported,
    VERSION,
} from "./engine/engine.js";
