// reference tile names from the Kenney Voxel Pack (see atlas.ts). Flags are split
// per the design review so culling, AO, collision and render-mode are independent.

export const enum Block {
    AIR = 0,
    STONE = 1,
    DIRT = 2,
    GRASS = 3,
    SAND = 4,
    SNOW = 5,
    WATER = 6,
    LOG = 7,
    LEAVES = 8,
    PLANKS = 9,
    GLASS = 10,
    BRICK = 11,
    COAL_ORE = 12,
    IRON_ORE = 13,
